-- Complete six-week quiz content and answer keys.
-- This migration is intentionally additive and safe to run after 0005.

alter table public.quizzes
  add column if not exists is_available boolean not null default true;

alter table public.quiz_questions
  alter column correct_option_index drop not null;

update public.courses
set passing_score = greatest(passing_score, 70);

update public.quizzes
set passing_score = greatest(passing_score, 70)
where id in ('quiz-week-1', 'quiz-week-2', 'quiz-week-3', 'quiz-week-4', 'quiz-week-5', 'quiz-week-6');

on conflict (id) do update set
  quiz_id = excluded.quiz_id,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_option_index = excluded.correct_option_index,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order;

update public.quizzes as quiz
set is_available = exists (
  select 1 from public.quiz_questions question where question.quiz_id = quiz.id
)
and not exists (
  select 1 from public.quiz_questions question
  where question.quiz_id = quiz.id and question.correct_option_index is null
)
where quiz.id in ('quiz-week-1', 'quiz-week-2', 'quiz-week-3', 'quiz-week-4', 'quiz-week-5', 'quiz-week-6');
